styles:
.b-press-outlets {
    container-type: inline-size;
}

.b-press-outlets__title {
    margin: 0 0 1em;
}

.b-press-outlets__group + .b-press-outlets__group {
    margin-top: 2.5em;
}

.b-press-outlets__heading {
    margin: 0 0 1em;
}

/* Up to four across, fewer when a card would be narrower than 14em. */
.b-press-outlets__list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, 14em), 1fr));
    gap: 1.5em;
    margin: 0;
    padding: 0;
    list-style: none;
}

/* A grid or flex box outranks the browser's own [hidden] rule. */
.b-press-outlets__list[hidden],
.b-press-outlets__card[hidden],
.b-press-outlets__group[hidden] {
    display: none;
}

.b-press-outlets__item {
    min-width: 0;
}

.b-press-outlets__card {
    display: flex;
    flex-direction: column;
    gap: 0.5em;
    box-sizing: border-box;
    height: 100%;
    padding: 1.25em;
    border: 1px solid color-mix(in srgb, currentColor 15%, transparent);
    border-radius: 0.75em;
}

.b-press-outlets__logo {
    display: block;
    width: auto;
    max-width: 100%;
    min-width: 0;
    height: auto;
    max-height: 2.5em;
    object-fit: contain;
    object-position: left center;
}

.b-press-outlets__name {
    margin: 0;
    font-size: 1.05em;
}

.b-press-outlets__name a {
    color: inherit;
}

.b-press-outlets__summary {
    flex: 1;
    margin: 0;
}

.b-press-outlets__count {
    margin: 0;
    font-size: 0.9em;
    opacity: 0.7;
}
